import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

interface AccentOption {
  readonly id: Accent;
  readonly label: string;
}

const OPTIONS: readonly AccentOption[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const checkedIndex = OPTIONS.findIndex((option) => option.id === value);
  // Roving tabindex: the checked option is the single tab stop. If the value
  // matches nothing, the first option takes that role so the group stays reachable.
  const tabStop = checkedIndex === -1 ? 0 : checkedIndex;

  function choose(index: number): void {
    onChange(OPTIONS[index].id);
    buttons.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    const last = OPTIONS.length - 1;
    let next: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }
    event.preventDefault();
    choose(next);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {OPTIONS.map((option, index) => {
        const checked = option.id === value;
        return (
          <button
            key={option.id}
            ref={(element) => {
              buttons.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={index === tabStop ? 0 : -1}
            className="accent-option"
            onClick={() => onChange(option.id)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-swatch" data-accent={option.id} aria-hidden="true" />
            <span className="accent-name">{option.label}</span>
            {checked && (
              <svg className="accent-check" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
                <path d="M3.5 8.5l3 3 6-7" />
              </svg>
            )}
          </button>
        );
      })}
    </div>
  );
}
```

